create or replace function public.get_my_property_payment_timeline(_order_id uuid) returns table(event_id text,event_type text,event_label text,amount numeric,status text,reference text,event_at timestamptz,balance_after numeric) language sql security definer set search_path=public as $$ with base as (select o.id,o.user_id,o.total_amount from public.orders o where o.id=_order_id and o.user_id=auth.uid()), events as (select 'payment:'||pr.id::text event_id, case when lower(coalesce(pr.type,'')) like '%document%' then 'documentation' else 'land' end event_type, case when lower(coalesce(pr.type,'')) like '%document%' then 'Documentation payment' else 'Land payment' end event_label, pr.amount, pr.status, pr.reference, pr.created_at event_at from public.payment_requests pr join base b on b.user_id=pr.user_id where pr.status in ('approved','completed','paid') and (pr.reference=b.id::text or pr.reference=(select payment_reference from public.orders where id=b.id) or pr.description ilike '%'||b.id::text||'%') union all select 'documentation:'||d.id::text,'documentation','Documentation payment',d.amount,d.status,d.reference,d.created_at from public.estate_documentation_payments d join base b on b.user_id=d.user_id where d.status in ('approved','completed','paid')) select e.event_id,e.event_type,e.event_label,e.amount,e.status,e.reference,e.event_at,greatest(b.total_amount-sum(case when e.event_type='land' then e.amount else 0 end) over(order by e.event_at,e.event_id rows between unbounded preceding and current row),0) from events e cross join base b order by e.event_at desc $$; revoke all on function public.get_my_property_payment_timeline(uuid) from public; grant execute on function public.get_my_property_payment_timeline(uuid) to authenticated;
